import{_ as r,c as a,o as e,ag as n}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"权限","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/permissions.md","filePath":"zh-CN/guide/permissions.md","lastUpdated":1791311600000}'),o={name:"zh-CN/guide/permissions.md"};function d(s,t,l,i,h,p){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h1><p>nPlyr 刻意<strong>精简权限</strong>。因为它是一个媒体播放器（而非剪贴板或录屏工具），它<strong>不</strong>请求辅助功能或屏幕录制权限。唯一可能出现的权限，是任何需要网络与文件的应用都需要的那些标准权限。</p><h2 id="网络访问" tabindex="-1">网络访问 <a class="header-anchor" href="#网络访问" aria-label="Permalink to &quot;网络访问&quot;">​</a></h2><p>流媒体、嗅探与小程序源都需要出站网络访问。在 macOS 上，App Store 沙盒默认允许——<strong>不会有任何提示</strong>，也无需手动授权。</p><h2 id="文件与文件夹" tabindex="-1">文件与文件夹 <a class="header-anchor" href="#文件与文件夹" aria-label="Permalink to &quot;文件与文件夹&quot;">​</a></h2><ul><li><strong>打开本地文件</strong>使用标准的 macOS 打开面板，因此由你自己挑选文件；不需要任何整体文件夹访问权限。</li><li><strong>保存下载</strong>会写入你的<strong>下载</strong>文件夹（或你选择的文件夹）。首次下载时，macOS 可能会弹出沙盒提示以确认位置。授权一次，nPlyr 就会记住该选择。</li></ul><p>如果之后移动了 nPlyr 的数据或撤销了访问，你可以在<strong>系统设置 → 隐私与安全性 → 文件与文件夹</strong>中重新授权。</p><h2 id="通知-可选" tabindex="-1">通知（可选） <a class="header-anchor" href="#通知-可选" aria-label="Permalink to &quot;通知（可选）&quot;">​</a></h2><p>下载完成时，nPlyr 可能会显示一个本地通知。这是可选的，可在<strong>系统设置 → 通知 → nPlyr</strong> 中关闭。</p><h2 id="nplyr-不请求什么" tabindex="-1">nPlyr 不请求什么 <a class="header-anchor" href="#nplyr-不请求什么" aria-label="Permalink to &quot;nPlyr 不请求什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>是否需要</th><th>原因</th></tr></thead><tbody><tr><td>辅助功能</td><td>否</td><td>键盘快捷键使用应用内事件监视器，而非全局辅助功能控制。</td></tr><tr><td>屏幕录制</td><td>否</td><td>nPlyr 播放并抓取<em>网络</em>媒体；它从不录制你的屏幕。</td></tr><tr><td>完全磁盘访问</td><td>否</td><td>所有文件访问都经由打开/保存面板或下载文件夹进行。</td></tr><tr><td>相机 / 麦克风</td><td>否</td><td>nPlyr 是一个观看工具；它不捕获输入设备。</td></tr></tbody></table><p>如果你看到此处未列出的权限提示，几乎可以肯定来自某个小程序或浏览器访问的特定站点——而非核心应用。如果看起来有什么不对，请参阅<a href="/zh-CN/guide/troubleshooting.html">故障排查</a>。</p>',12)])])}const g=r(o,[["render",d]]);export{m as __pageData,g as default};
